cat > /tmp/process_documents.pl << 'ENDSCRIPT'
#!/usr/bin/perl
use strict;
use warnings;
use File::Copy;
use File::Spec;

# Create output directories
mkdir("/app/invoices") unless -d "/app/invoices";
mkdir("/app/other") unless -d "/app/other";

my $docs_dir = "/app/documents";
my @files = glob("$docs_dir/*");

my @invoices_data;

foreach my $file (@files) {
    next unless -f $file;
    my $filename = (File::Spec->splitpath($file))[2];

    # Extract text from file
    my $text = extract_text($file);

    # Classify as invoice or other
    my $is_invoice = is_invoice($text);

    if ($is_invoice) {
        # Move to invoices dir
        my $dest = "/app/invoices/$filename";
        move($file, $dest) or die "Cannot move $file to $dest: $!";

        # Extract amounts
        my $total_amount = extract_total_amount($text);
        my $vat_amount = extract_vat_amount($text);

        push @invoices_data, {
            filename => $filename,
            total_amount => $total_amount // '',
            vat_amount => $vat_amount // ''
        };
    } else {
        # Move to other dir
        my $dest = "/app/other/$filename";
        move($file, $dest) or die "Cannot move $file to $dest: $!";
    }
}

# Create CSV with summary
create_csv(@invoices_data);

sub extract_text {
    my ($file) = @_;
    my $text = '';

    if ($file =~ /\.pdf$/i) {
        $text = `pdftotext "$file" - 2>/dev/null`;
    } elsif ($file =~ /\.jpg$/i) {
        $text = `tesseract "$file" stdout 2>/dev/null`;
    }

    return $text;
}

sub is_invoice {
    my ($text) = @_;
    return 0 unless $text;

    my $lower = lc($text);

    # Check for invoice-related keywords
    return 1 if $lower =~ /\binvoice\b/;
    return 1 if $lower =~ /\bbill\b/ && $lower =~ /\b(amount|total|due)\b/;
    return 1 if $lower =~ /\breceipt\b/;
    return 1 if $lower =~ /\binvoice.*number\b/;
    return 1 if $lower =~ /\b(amount\s+due|total\s+amount|grand\s+total)\b/;

    return 0;
}

sub extract_total_amount {
    my ($text) = @_;
    return '' unless $text;

    my $lower = lc($text);

    # Look for "Total" first (has priority)
    if ($lower =~ /\btotal\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    # Then "Amount Due"
    if ($lower =~ /\bamount\s+due\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    # Then "Grand Total"
    if ($lower =~ /\bgrand\s+total\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    return '';
}

sub extract_vat_amount {
    my ($text) = @_;
    return '' unless $text;

    my $lower = lc($text);

    # Look for VAT
    if ($lower =~ /\bvat\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    # Look for Tax
    if ($lower =~ /\btax\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    # Look for GST
    if ($lower =~ /\bgst\s*:?\s*(\$?[\d,]+\.?\d*)/i) {
        my $amount = $1;
        $amount =~ s/\$|,//g;
        return $amount if $amount;
    }

    return '';
}

sub create_csv {
    my (@invoices) = @_;

    open my $fh, '>', '/app/invoices/summary.csv' or die "Cannot create summary.csv: $!";

    print $fh "filename,total_amount,vat_amount\n";

    my $total_sum = 0;
    my $vat_sum = 0;

    foreach my $inv (@invoices) {
        my $filename = $inv->{filename};
        my $total = $inv->{total_amount} // '';
        my $vat = $inv->{vat_amount} // '';

        print $fh "$filename,$total,$vat\n";

        $total_sum += $total if $total;
        $vat_sum += $vat if $vat;
    }

    print $fh "total,$total_sum,$vat_sum\n";

    close $fh;
}
ENDSCRIPT
chmod +x /tmp/process_documents.pl
perl /tmp/process_documents.pl
